/* Original N2 teaching selection, not an official exhaustive syllabus or test bank. */
const N2_UNITS=[],N2_MODULES=['时间、过程与转折','对比、条件与变化','判断、责任与情感','范围、立场与论证'];
function n2Add(title,vocab,points,reading,listening){
 const id='n2u'+String(N2_UNITS.length+1).padStart(2,'0');
 const gs=points.map(([title,rule,pitfall,examples,q,options,answer,why],i)=>({id:id+'g'+i,title,rule,pitfall,examples,q,options:options.split('|'),answer,why}));
 const text=([text,translation,qs],kind)=>({text,translation,ids:qs.map((_,i)=>id+kind+i),questions:qs.map(([q,options,answer,why],i)=>({id:id+kind+i,q,options:options.split('|'),answer,why}))});
 N2_UNITS.push({id,title,module:Math.floor(N2_UNITS.length/6),vocab:vocab.split(';').map(v=>v.split('|')),grammar:gs,reading:text(reading,'r'),listening:text(listening,'l')});
}
